import{_ as t,o as r,c as a,a5 as o}from"./chunks/framework.DvE3tBec.js";const d=JSON.parse('{"title":"Getting started for users","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/0.4/getting-started.md","filePath":"documentation/0.4/getting-started.md","lastUpdated":1766403361000}'),n={name:"documentation/0.4/getting-started.md"};function i(s,e,l,p,g,u){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="getting-started-for-users" tabindex="-1">Getting started for users <a class="header-anchor" href="#getting-started-for-users" aria-label="Permalink to &quot;Getting started for users&quot;">​</a></h1><p>Currently, there are three official client libraries, a web-based interface for openEO and a QGIS plugin.</p><p>If you are <strong>unfamiliar</strong> with programming, you could start using the <a href="https://editor.openeo.org" target="_blank" rel="noreferrer">web-based editor for openEO</a>. It supports visual modelling of your algorithms and a simplified JavaScript based access to the openEO workflows and providers. openEO can also be used in QGIS through a <a href="https://plugins.qgis.org/plugins/openeo_plugin/" target="_blank" rel="noreferrer">QGIS plugin</a>.</p><p>If you are <strong>familiar</strong> with programming, you could choose a client library for three programming languages:</p><ul><li><a href="https://www.npmjs.com/package/@openeo/js-client" target="_blank" rel="noreferrer">JavaScript</a> (client-side and server-side)</li><li><a href="https://pypi.org/project/openeo/" target="_blank" rel="noreferrer">Python</a></li><li><a href="https://github.com/Open-EO/openeo-r-client" target="_blank" rel="noreferrer">R</a></li></ul><p>Follow the links above to find usage instructions for each of the client libraries.</p><h2 id="contribute" tabindex="-1">Contribute <a class="header-anchor" href="#contribute" aria-label="Permalink to &quot;Contribute&quot;">​</a></h2><p>Didn&#39;t find your programming language? You can also access the <a href="./developers/api/reference.html">openEO API</a> implementations directly or start <a href="./developers/clients/getting-started.html">implementing your own client library</a>.</p><p>If you are missing any functionality in the API feel free to <a href="https://github.com/Open-EO/openeo-api/issues" target="_blank" rel="noreferrer">open an issue</a> or actively start proposing API changes as Pull Requests.</p><p>Feel free to contact us for further assistance.</p>',10)])])}const f=t(n,[["render",i]]);export{d as __pageData,f as default};
